	alphaClip: f32,
	minPixelSize: f32,
	minContribution: f32,
	foveationStrength: f32,
	foveationCenter: f32,
	antiAliasFilterSize: f32,
	viewMatrix: mat4x4f,
	viewProj: mat4x4f,
